// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(uint256 newLimit) public {
        vm.prank(address(this));
        bool ok;
        try c.AdjustBetAmounts(newLimit) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.currentBetLimit() == newLimit);
    }
}
